// ARCH000 container reader tests.
//
// The container is exercised through synthetic files rather than the shipped
// archives, so the suite runs on a machine with no game install and so that a
// failure points at the container layer instead of at 17 MB of game data.
//
// Where a payload is ciphered the expected bytes come from
// tests/bogocrypt1_fixtures.inc, which is generated by
// tools/gen_bogocrypt1_fixtures.py from the Python reference decoder. These
// tests therefore assert the C++ container layer agrees with the reference,
// not merely with itself.

#include "test_harness.hpp"

#include <filesystem>
#include <fstream>
#include <string>
#include <system_error>
#include <vector>

#include "isaec/data/archive.hpp"
#include "isaec/platform/types.hpp"

using isaec::u8;
using isaec::u16;
using isaec::u32;
using isaec::usize;
using isaec::data::Archive;
using isaec::data::kArchiveHeaderSize;

// The generated fixtures spell u8/u32/usize unqualified, so they must follow the
// using-declarations above.
#include "bogocrypt1_fixtures.inc"

namespace {

void put_u16le(std::vector<u8>& out, u16 value) {
    out.push_back(static_cast<u8>(value & 0xFFu));
    out.push_back(static_cast<u8>((value >> 8) & 0xFFu));
}

void put_u32le(std::vector<u8>& out, u32 value) {
    out.push_back(static_cast<u8>(value & 0xFFu));
    out.push_back(static_cast<u8>((value >> 8) & 0xFFu));
    out.push_back(static_cast<u8>((value >> 16) & 0xFFu));
    out.push_back(static_cast<u8>((value >> 24) & 0xFFu));
}

u32 load_u32le(const std::vector<u8>& blob, usize at) {
    return static_cast<u32>(blob[at]) | (static_cast<u32>(blob[at + 1]) << 8) |
           (static_cast<u32>(blob[at + 2]) << 16) | (static_cast<u32>(blob[at + 3]) << 24);
}

void patch_u32le(std::vector<u8>& blob, usize at, u32 value) {
    blob[at + 0] = static_cast<u8>(value & 0xFFu);
    blob[at + 1] = static_cast<u8>((value >> 8) & 0xFFu);
    blob[at + 2] = static_cast<u8>((value >> 16) & 0xFFu);
    blob[at + 3] = static_cast<u8>((value >> 24) & 0xFFu);
}

const char kMagic[7] = {'A', 'R', 'C', 'H', '0', '0', '0'};

// One entry's worth of input. `gap` bytes are emitted after the payload, which
// is how the obfuscator padded an entry's final cipher block: the cipher
// consumed bytes belonging to the gap in front of the next entry, and those
// bytes are padding, never payload.
struct Slot {
    std::vector<u8> payload;
    usize gap = 0;
    u32 special = 0;
    u32 name_hash = 0;
    u32 checksum = 0;
    // Size written to the entry table. Defaults to the payload length; a
    // stored entry overrides it, because its nine-byte record header is not
    // part of the asset.
    usize asset_size = static_cast<usize>(-1);
};

std::vector<u8> build(u8 mode, const std::vector<Slot>& slots) {
    std::vector<u8> blob;
    blob.reserve(kArchiveHeaderSize + 64);

    for (char c : kMagic) {
        blob.push_back(static_cast<u8>(c));
    }
    blob.push_back(mode);
    put_u32le(blob, 0);  // index_offset, patched once the payloads are laid out
    put_u16le(blob, static_cast<u16>(slots.size()));

    std::vector<u32> offsets;
    offsets.reserve(slots.size());
    for (const Slot& slot : slots) {
        offsets.push_back(static_cast<u32>(blob.size()));
        blob.insert(blob.end(), slot.payload.begin(), slot.payload.end());
        for (usize i = 0; i < slot.gap; ++i) {
            blob.push_back(0x5A);
        }
    }

    const u32 index_offset = static_cast<u32>(blob.size());
    patch_u32le(blob, 8, index_offset);
    for (usize i = 0; i < slots.size(); ++i) {
        put_u32le(blob, slots[i].name_hash);
        put_u32le(blob, slots[i].special);
        put_u32le(blob, offsets[i]);
        const usize asset = slots[i].asset_size == static_cast<usize>(-1)
                                ? slots[i].payload.size()
                                : slots[i].asset_size;
        put_u32le(blob, static_cast<u32>(asset));
        put_u32le(blob, slots[i].checksum);
    }
    return blob;
}

std::filesystem::path scratch(const char* name, const std::vector<u8>& blob) {
    const std::filesystem::path dir =
        std::filesystem::temp_directory_path() / "isaec_archive_tests";
    std::error_code ignored;
    std::filesystem::create_directories(dir, ignored);
    const std::filesystem::path path = dir / name;
    std::ofstream out(path, std::ios::binary | std::ios::trunc);
    out.write(reinterpret_cast<const char*>(blob.data()),
              static_cast<std::streamsize>(blob.size()));
    out.close();
    return path;
}
std::vector<u8> stored_record(const std::vector<u8>& payload) {
    const u32 size = static_cast<u32>(payload.size());
    std::vector<u8> record;
    put_u16le(record, static_cast<u16>(size + 5));
    record.push_back(0x00);
    record.push_back(0x80);
    record.push_back(0x01);
    put_u16le(record, static_cast<u16>(size));
    record.push_back(static_cast<u8>((~size) & 0xFFu));
    record.push_back(0xFD);
    record.insert(record.end(), payload.begin(), payload.end());
    return record;
}

}  // namespace

ISAEC_TEST(archive_open_reports_a_missing_file) {
    Archive archive;
    const std::filesystem::path path =
        std::filesystem::temp_directory_path() / "isaec_archive_tests" / "definitely_absent.a";
    std::error_code ignored;
    std::filesystem::remove(path, ignored);

    CHECK(!archive.open(path));
    CHECK(!archive.error().empty());
    CHECK(archive.entries().empty());
}

ISAEC_TEST(archive_open_rejects_bad_magic) {
    std::vector<Slot> slots(1);
    slots[0].payload = {0x01, 0x02, 0x03, 0x04};
    std::vector<u8> blob = build(0x00, slots);
    blob[3] = 'X';

    Archive archive;
    CHECK(!archive.open(scratch("bad_magic.a", blob)));
    CHECK(!archive.error().empty());
}

ISAEC_TEST(archive_open_rejects_zero_entry_count) {
    std::vector<u8> blob;
    for (char c : kMagic) {
        blob.push_back(static_cast<u8>(c));
    }
    blob.push_back(0x00);
    put_u32le(blob, kArchiveHeaderSize);
    put_u16le(blob, 0);

    Archive archive;
    CHECK(!archive.open(scratch("zero_count.a", blob)));
    CHECK(!archive.error().empty());
}

ISAEC_TEST(archive_open_rejects_an_index_that_does_not_match_the_file_size) {
    std::vector<Slot> slots(2);
    slots[0].payload = {0x01, 0x02};
    slots[1].payload = {0x03, 0x04};
    std::vector<u8> blob = build(0x00, slots);
    patch_u32le(blob, 8, load_u32le(blob, 8) + 4);

    Archive archive;
    CHECK(!archive.open(scratch("index_mismatch.a", blob)));
    CHECK(!archive.error().empty());
}

ISAEC_TEST(archive_open_rejects_a_first_payload_offset_below_the_header) {
    std::vector<Slot> slots(2);
    slots[0].payload = {0x01, 0x02};
    slots[1].payload = {0x03, 0x04};
    std::vector<u8> blob = build(0x00, slots);
    patch_u32le(blob, load_u32le(blob, 8) + 8, 13);

    Archive archive;
    CHECK(!archive.open(scratch("first_offset.a", blob)));
    CHECK(!archive.error().empty());
}

ISAEC_TEST(archive_open_rejects_an_unsorted_offset_column) {
    std::vector<Slot> slots(2);
    slots[0].payload = {0x01, 0x02};
    slots[1].payload = {0x03, 0x04};
    std::vector<u8> blob = build(0x00, slots);
    const usize index = load_u32le(blob, 8);
    const u32 first = load_u32le(blob, index + 8);
    const u32 second = load_u32le(blob, index + 28);
    patch_u32le(blob, index + 8, second);
    patch_u32le(blob, index + 28, first);

    Archive archive;
    CHECK(!archive.open(scratch("unsorted.a", blob)));
    CHECK(!archive.error().empty());
}

ISAEC_TEST(archive_open_parses_the_header_and_the_entry_table) {
    std::vector<Slot> slots(3);
    slots[0].payload = {0xAA};
    slots[0].name_hash = 0x503F9B44u;
    slots[0].special = 0x9BB3F301u;
    slots[0].checksum = 0x915B0BDFu;
    slots[1].payload = {0xBB, 0xCC};
    slots[1].name_hash = 0x11223344u;
    slots[1].special = 0x55667788u;
    slots[2].payload = {0xDD, 0xEE, 0xFF};
    slots[2].name_hash = 0x00000002u;
    slots[2].special = 0x00000003u;

    Archive archive;
    REQUIRE(archive.open(scratch("parse.a", build(0x00, slots))));
    CHECK(archive.mode() == 0x00);
    REQUIRE(archive.entries().size() == 3);

    CHECK(archive.entries()[0].name_hash == 0x503F9B44u);
    CHECK(archive.entries()[0].special == 0x9BB3F301u);
    CHECK(archive.entries()[0].offset == kArchiveHeaderSize);
    CHECK(archive.entries()[0].size == 1);
    CHECK(archive.entries()[0].checksum == 0x915B0BDFu);
    CHECK(archive.entries()[1].offset == kArchiveHeaderSize + 1);
    CHECK(archive.entries()[1].size == 2);
    CHECK(archive.entries()[2].offset == kArchiveHeaderSize + 3);
    CHECK(archive.entries()[2].size == 3);

    const std::string description = archive.describe();
    CHECK(description.find("mode=0x00") != std::string::npos);
    CHECK(description.find("entries=3") != std::string::npos);
    CHECK(description.find("xor") != std::string::npos);
}

ISAEC_TEST(archive_cipher_span_reaches_the_next_entry_not_the_asset_length) {
    std::vector<Slot> slots(3);
    slots[0].payload = std::vector<u8>(10, 0x11);
    slots[0].gap = 2;
    slots[1].payload = std::vector<u8>(7, 0x22);
    slots[1].gap = 1;
    slots[2].payload = std::vector<u8>(5, 0x33);

    Archive archive;
    REQUIRE(archive.open(scratch("spans.a", build(0x00, slots))));

    // Entry 0 is 10 bytes of asset but the cipher consumed 12, because the
    // obfuscator borrowed the two gap bytes. Passing 10 instead of 12 leaves a
    // corrupt tail; on graphics.a that is the difference between a valid and an
    // invalid IEND CRC on 318 of 2300 entries.
    CHECK(archive.cipher_span(0) == 12);
    CHECK(archive.cipher_span(1) == 8);
    // The final entry has no successor, so its span runs to end of file. That
    // includes the twenty-byte index that trails the payloads; the reader and
    // the Python reference agree on this, and everything past the recorded size
    // is truncated away.
    CHECK(archive.cipher_span(2) == 5 + 3 * 20);
}

ISAEC_TEST(archive_record_header_exposes_the_stored_flag) {
    const std::vector<u8> payload = {0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A};
    std::vector<Slot> slots(1);
    slots[0].payload = stored_record(payload);
    slots[0].asset_size = payload.size();

    Archive archive;
    REQUIRE(archive.open(scratch("stored.a", build(0x02, slots))));
    REQUIRE(archive.entries().size() == 1);
    // The recorded size excludes the nine-byte record header.
    CHECK(archive.entries()[0].size == payload.size());
    CHECK(archive.is_stored(0));

    // RecordHeader names are positional rather than semantic: `reserved` is the
    // always-zero byte at offset 2, the 0x80 stored flag lands in `flags`, and
    // `kind` is the separate byte at offset 4.
    const auto header = archive.record_header(0);
    REQUIRE(header.has_value());
    CHECK(header->declared_total == payload.size() + 5);
    CHECK(header->reserved == 0x00);
    CHECK(header->flags == 0x80);
    CHECK(header->kind == 0x01);
    CHECK(header->declared_size == payload.size());
    CHECK(header->length_check == static_cast<u8>((~payload.size()) & 0xFFu));
    CHECK(header->trailer == 0xFD);
}

ISAEC_TEST(archive_stored_predicate_needs_every_length_field_to_agree) {
    const std::vector<u8> payload = {0x01, 0x02, 0x03, 0x04, 0x05};

    // declared_total lives at bytes 0-1, declared_size at 5-6 and the length
    // check at 7. Breaking any one of them must fall back to "not stored".
    const usize broken_byte[3] = {0, 5, 7};
    const char* const field[3] = {"declared_total", "declared_size", "length_check"};

    for (usize variant = 0; variant < 3; ++variant) {
        std::vector<Slot> slots(1);
        slots[0].payload = stored_record(payload);
        slots[0].asset_size = payload.size();
        slots[0].payload[broken_byte[variant]] ^= 0xFFu;

        Archive archive;
        REQUIRE(archive.open(scratch("predicate.a", build(0x02, slots))));
        if (archive.is_stored(0)) {
            ::isaec::test::fail_now(std::string("stored predicate accepted a broken ") +
                                    field[variant]);
        }
    }
}

ISAEC_TEST(archive_stored_predicate_is_ignored_outside_mode_0x02) {
    const std::vector<u8> payload = {0x10, 0x20, 0x30, 0x40, 0x50, 0x60};
    std::vector<Slot> slots(1);
    slots[0].payload = stored_record(payload);
    slots[0].asset_size = payload.size();

    Archive archive;
    REQUIRE(archive.open(scratch("stored_mode00.a", build(0x00, slots))));
    // is_stored only inspects the record header, so it answers true; decode is
    // what routes on the mode. Pinning this so a future mode check has to be a
    // deliberate change rather than an accident.
    CHECK(archive.is_stored(0));
}

ISAEC_TEST(archive_decode_returns_a_stored_payload_verbatim) {
    const std::vector<u8> png_magic = {0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A, 0xFF};
    std::vector<Slot> slots(2);
    slots[0].payload = stored_record(png_magic);
    slots[0].asset_size = png_magic.size();
    slots[1].payload = stored_record({0xDE, 0xAD, 0xBE, 0xEF});
    slots[1].asset_size = 4;

    Archive archive;
    REQUIRE(archive.open(scratch("verbatim.a", build(0x02, slots))));

    std::vector<u8> out;
    REQUIRE(archive.decode(0, out));
    CHECK(out.size() == png_magic.size());
    CHECK(out == png_magic);

    std::vector<u8> second;
    REQUIRE(archive.decode(1, second));
    CHECK(second.size() == 4);
    CHECK(second[0] == 0xDE);
    CHECK(second[3] == 0xEF);
}

ISAEC_TEST(archive_decode_refuses_the_modes_this_build_cannot_verify) {
    // Mode 0x01 decodes real XML and then diverges in length; mode 0x02's PRNG
    // keystream is indistinguishable from noise on real archives. Returning
    // either would hand the renderer garbage, so the reader refuses.
    std::vector<Slot> lzw(1);
    lzw[0].payload = std::vector<u8>(64, 0x7B);
    Archive lzw_archive;
    REQUIRE(lzw_archive.open(scratch("lzw.a", build(0x01, lzw))));
    std::vector<u8> lzw_out;
    CHECK(!lzw_archive.decode(0, lzw_out));
    CHECK(lzw_archive.error().find("0x01") != std::string::npos);

    std::vector<Slot> prng(1);
    prng[0].payload = std::vector<u8>(64, 0x3C);
    Archive prng_archive;
    REQUIRE(prng_archive.open(scratch("prng.a", build(0x02, prng))));
    std::vector<u8> prng_out;
    CHECK(!prng_archive.decode(0, prng_out));
    CHECK(prng_archive.error().find("0x02") != std::string::npos);
}

ISAEC_TEST(archive_decode_rejects_an_index_outside_the_entry_table) {
    std::vector<Slot> slots(1);
    slots[0].payload = {0x01, 0x02};
    Archive archive;
    REQUIRE(archive.open(scratch("range.a", build(0x00, slots))));

    std::vector<u8> out;
    CHECK(!archive.decode(1, out));
    CHECK(!archive.decode(static_cast<usize>(-1), out));
    CHECK(!archive.is_stored(1));
    CHECK(!archive.record_header(1).has_value());
    CHECK(archive.cipher_span(99) == 0);
}

ISAEC_TEST(archive_decode_of_a_xor_entry_matches_the_reference_decoder) {
    // Each fixture's input is already ciphered over exactly `input_size` bytes.
    // Laying it out as entry 0 of a two-entry container makes that entry's cipher
    // span exactly `input_size`, so the whole container path is checked against
    // the generated expectation without needing an encoder.
    const usize fixture_count = sizeof(kBogocrypt1Fixtures) / sizeof(kBogocrypt1Fixtures[0]);
    REQUIRE(fixture_count > 0);

    for (usize i = 0; i < fixture_count; ++i) {
        const Bogocrypt1Fixture& fixture = kBogocrypt1Fixtures[i];

        std::vector<Slot> slots(2);
        slots[0].special = fixture.special_hash;
        slots[0].payload.assign(fixture.input, fixture.input + fixture.input_size);
        slots[1].payload = {0x00};

        std::vector<u8> blob = build(0x00, slots);
        // The asset is shorter than the cipher span whenever the original entry
        // borrowed padding bytes, so declare the short length.
        patch_u32le(blob, load_u32le(blob, 8) + 12, static_cast<u32>(fixture.size));

        Archive archive;
        REQUIRE(archive.open(scratch("xor_fixture.a", blob)));
        REQUIRE(archive.entries().size() == 2);
        CHECK(archive.cipher_span(0) == fixture.input_size);

        std::vector<u8> out;
        if (!archive.decode(0, out)) {
            ::isaec::test::fail_now(std::string("container rejected fixture ") + fixture.name);
        }
        if (out.size() != fixture.size) {
            ::isaec::test::fail_now(std::string("fixture ") + fixture.name + " produced " +
                                    std::to_string(out.size()) + " bytes, expected " +
                                    std::to_string(fixture.size));
        }
        for (usize b = 0; b < fixture.size; ++b) {
            if (out[b] != fixture.expected[b]) {
                ::isaec::test::fail_now(std::string("fixture ") + fixture.name +
                                        " differs from the reference at byte " +
                                        std::to_string(b));
            }
        }
    }
}
